<?php

namespace Database\Seeders;

use App\Models\User;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\Hash;

/**
 * Importa los registrantes del formulario externo (export lp(a)ction_entries.xlsx) como usuarios
 * de PRUEBA. Todos quedan con la contrasena 'Prueba2026' y marcados is_test = true.
 *
 *   php artisan db:seed --class=LpactionEntriesSeeder
 *
 * Idempotente: usa updateOrCreate por email, asi que se puede re-ejecutar sin duplicar.
 * La especialidad se guarda tal cual venia en el export (datos reales, con sus variantes); la
 * acreditacion SEAFORMEC se decide de forma insensible a tildes/mayusculas en el controlador.
 */
class LpactionEntriesSeeder extends Seeder
{
    public function run(): void
    {
        $password = Hash::make('Prueba2026');   // misma clave para todos

        foreach ($this->entries() as $e) {
            User::updateOrCreate(
                ['email' => $e['email']],
                [
                    'name'             => $e['name'] ?: 'Usuario',
                    'last_name'        => $e['last_name'],
                    'document_id'      => $e['document_id'],
                    'country'          => $e['country'],
                    'specialty'        => $e['specialty'],
                    'password'         => $password,
                    'accepted_privacy' => true,
                    'is_test'          => true,
                    'is_admin'         => false,
                ]
            );
        }

        $this->command->info('Seed lp(a)ction entries: '.count($this->entries()).' usuarios (clave Prueba2026).');
    }

